import React from 'react';
import 'tailwindcss/tailwind.css';

const Contact: React.FC = () => (
  <div className="p-6 bg-gray-100 rounded-lg shadow-md">
    <h2 className="text-2xl font-bold mb-4">Contact Me</h2>
    <form className="space-y-4">
      <input className="w-full px-4 py-2 border rounded-md" type="text" placeholder="Name" />
      <input className="w-full px-4 py-2 border rounded-md" type="email" placeholder="Email" />
      <textarea className="w-full px-4 py-2 border rounded-md" placeholder="Message"></textarea>
      <button className="bg-customBtn text-black px-4 py-2 rounded-md hover:bg-navbarHover" type="submit">Send</button>
    </form>
  </div>
);

export default Contact;
